@can('locations.manage')
    <button type="button" data-location-creator-open class="text-sm font-bold text-indigo-700 hover:text-indigo-900">+ Create new location</button>
    <dialog data-location-creator class="fixed left-1/2 top-1/2 m-0 max-h-[calc(100vh-2rem)] w-[calc(100vw-2rem)] max-w-xl -translate-x-1/2 -translate-y-1/2 overflow-hidden rounded-2xl border border-slate-200 bg-white p-0 shadow-2xl backdrop:bg-slate-950/50">
        <div class="border-b border-slate-100 bg-gradient-to-r from-indigo-50 to-white px-6 py-5"><div class="flex items-start justify-between gap-4"><div><p class="text-xs font-bold uppercase tracking-[.16em] text-indigo-500">Locations catalogue</p><h2 class="mt-1 text-xl font-bold text-slate-900">Create a saved location</h2><p class="mt-1 text-sm leading-6 text-slate-500">Search Google, choose the real place, then save the name customers will see.</p></div><button type="button" data-location-creator-close class="grid size-9 place-items-center rounded-lg text-xl text-slate-400 transition hover:bg-white hover:text-slate-700" aria-label="Close">×</button></div></div>
        <form data-location-creator-form class="flex max-h-[calc(100vh-11rem)] flex-col">
            <div class="min-h-0 overflow-y-auto px-6 py-6"><label class="admin-label">Search Google places</label>
            <input data-location-creator-search class="admin-input" autocomplete="off" placeholder="Start typing a place, airport or city…">
            <input data-location-creator-place-id type="hidden">
            <div data-location-creator-results class="mt-2 hidden max-h-52 overflow-y-auto rounded-xl border border-slate-200 bg-white shadow-lg"></div>
            <div data-location-creator-name-wrap class="mt-5 hidden rounded-xl border border-emerald-200 bg-emerald-50/60 p-4"><p data-location-creator-selected class="text-sm font-bold text-emerald-800"></p><label class="admin-label mt-4">Location name</label><input data-location-creator-name class="admin-input !bg-white" maxlength="150" placeholder="e.g. Zürich Airport"><p class="mt-1 text-xs text-emerald-700">Editable: this is the name customers and staff see. Changing it does not alter the selected Google Place ID.</p></div>
            <p data-location-creator-error class="mt-4 hidden rounded-lg bg-rose-50 px-3 py-2 text-sm font-medium text-rose-700"></p></div>
            <div class="flex shrink-0 justify-end gap-3 border-t border-slate-100 bg-slate-50 px-6 py-4"><button type="button" data-location-creator-close class="admin-button-soft">Cancel</button><button data-location-creator-save class="admin-button" disabled>Create location</button></div>
        </form>
    </dialog>
    <script>
        (() => {
            const dialog=document.querySelector('[data-location-creator]'); if(!dialog) return;
            const open=document.querySelector('[data-location-creator-open]'), closes=dialog.querySelectorAll('[data-location-creator-close]'), search=dialog.querySelector('[data-location-creator-search]'), results=dialog.querySelector('[data-location-creator-results]'), placeId=dialog.querySelector('[data-location-creator-place-id]'), name=dialog.querySelector('[data-location-creator-name]'), nameWrap=dialog.querySelector('[data-location-creator-name-wrap]'), selected=dialog.querySelector('[data-location-creator-selected]'), error=dialog.querySelector('[data-location-creator-error]'), form=dialog.querySelector('[data-location-creator-form]'), save=dialog.querySelector('[data-location-creator-save]');
            let timer;
            const reset=()=>{form.reset();results.replaceChildren();results.classList.add('hidden');nameWrap.classList.add('hidden');error.classList.add('hidden');save.disabled=true};
            open.addEventListener('click',()=>{reset();dialog.showModal();search.focus()});closes.forEach(button=>button.addEventListener('click',()=>dialog.close()));
            search.addEventListener('input',()=>{clearTimeout(timer);const term=search.value.trim();if(term.length<2){results.classList.add('hidden');return}timer=setTimeout(async()=>{try{const response=await fetch(`{{ route('admin.locations.search') }}?q=${encodeURIComponent(term)}`,{headers:{Accept:'application/json'}});const json=await response.json();results.replaceChildren();(json.data||[]).forEach(item=>{const button=document.createElement('button');button.type='button';button.className='block w-full px-4 py-3 text-left text-sm hover:bg-indigo-50';button.textContent=item.name;button.addEventListener('click',()=>{placeId.value=item.place_id;name.value=item.name;selected.textContent=`Google place selected: ${item.name}`;nameWrap.classList.remove('hidden');save.disabled=false;results.classList.add('hidden')});results.append(button)});if(!results.children.length)results.textContent='No matching places found.';results.classList.remove('hidden')}catch{results.textContent='Google search could not be completed.';results.classList.remove('hidden')}},280)});
            form.addEventListener('submit',async event=>{event.preventDefault();if(!placeId.value)return;save.disabled=true;error.classList.add('hidden');try{const response=await fetch(`{{ route('admin.locations.quick-store') }}`,{method:'POST',headers:{'Content-Type':'application/json','Accept':'application/json','X-CSRF-TOKEN':document.querySelector('meta[name="csrf-token"]').content},body:JSON.stringify({google_place_id:placeId.value,name:name.value})});const json=await response.json();if(!response.ok)throw new Error(json.message||'Location could not be created.');window.dispatchEvent(new CustomEvent('admin:location-created',{detail:json.data}));dialog.close()}catch(problem){error.textContent=problem.message;error.classList.remove('hidden');save.disabled=false}});
        })();
    </script>
@endcan
